import{_ as t,o,c as d,ag as a}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"TableType — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/TableType/TableType.figma-notes.md","filePath":"public/demos/src/components/TableType/TableType.figma-notes.md"}'),r={name:"public/demos/src/components/TableType/TableType.figma-notes.md"};function i(n,e,s,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tabletype-—-figma-notes" tabindex="-1">TableType — Figma Notes <a class="header-anchor" href="#tabletype-—-figma-notes" aria-label="Permalink to &quot;TableType — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Component <strong>Built:</strong> 2026-08-25 (Seating Planner module, wave 1) <strong>Files:</strong> <code>TableType.css</code>, <code>TableType.html</code>, <code>TableType.figma-notes.md</code></p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3470:85494</code></li></ul><h2 id="variant-matrix-5-variants" tabindex="-1">Variant matrix (5 variants) <a class="header-anchor" href="#variant-matrix-5-variants" aria-label="Permalink to &quot;Variant matrix (5 variants)&quot;">​</a></h2><p>Axes are <strong>Type × Tier</strong>. Tier has a single value (<code>Component</code>), so it produces no CSS.</p><table tabindex="0"><thead><tr><th>Type</th><th>Tier</th><th>Node</th><th>CSS</th><th>Figma width</th></tr></thead><tbody><tr><td>VIP</td><td>Component</td><td><code>3470:85488</code></td><td><code>.table-type.table-type--vip</code></td><td>35px</td></tr><tr><td>Head Table</td><td>Component</td><td><code>3470:85489</code></td><td><code>.table-type.table-type--head-table</code></td><td>82px</td></tr><tr><td>Gold</td><td>Component</td><td><code>3470:85485</code></td><td><code>.table-type.table-type--gold</code></td><td>47px</td></tr><tr><td>Silver</td><td>Component</td><td><code>3470:85492</code></td><td><code>.table-type.table-type--silver</code></td><td>53px</td></tr><tr><td>Bronze</td><td>Component</td><td><code>3470:85484</code></td><td><code>.table-type.table-type--bronze</code></td><td>60px</td></tr></tbody></table><p>All five are 18px tall; widths are content-driven, which the CSS reproduces with <code>display: inline-flex</code> + <code>white-space: nowrap</code> rather than fixed widths. Verified: the built component renders 18px tall for every variant.</p><p>VIP is Figma&#39;s default variant, so <code>.table-type</code> with no modifier resolves to the VIP colour.</p><h2 id="colour-model" tabindex="-1">Colour model <a class="header-anchor" href="#colour-model" aria-label="Permalink to &quot;Colour model&quot;">​</a></h2><p>The tier colour is <strong>picked by the user from a colour picker in the product</strong>, so it is a runtime value, not a design token (confirmed by the designer 2026-08-24). One custom property drives all three paints, per the designer&#39;s rule:</p><table tabindex="0"><thead><tr><th>Paint</th><th>Rule</th><th>CSS</th></tr></thead><tbody><tr><td>background</td><td>80% white over the tier colour</td><td><code>color-mix(in srgb, #ffffff 80%, var(--table-type-color))</code></td></tr><tr><td>border</td><td>70% white over the tier colour</td><td><code>color-mix(in srgb, #ffffff 70%, var(--table-type-color))</code></td></tr><tr><td>text</td><td>25% black over the tier colour</td><td><code>color-mix(in srgb, #000000 25%, var(--table-type-color))</code></td></tr></tbody></table><p>Figma expresses the background as two stacked linear-gradients — <code>rgba(255,255,255,0.8)</code> over a solid tier colour — which composites to the same result as the 80% mix.</p><p>Setting <code>--table-type-color</code> on an instance recolours the whole pill. The five modifiers are presets only.</p><h3 id="verification-against-figma" tabindex="-1">Verification against Figma <a class="header-anchor" href="#verification-against-figma" aria-label="Permalink to &quot;Verification against Figma&quot;">​</a></h3><p>12 of 15 computed values are <strong>exact</strong>. The rest:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Part</th><th>Built</th><th>Figma</th><th>Δ</th></tr></thead><tbody><tr><td>VIP</td><td>border</td><td><code>#B3D5E2</code></td><td><code>#B2D5E2</code></td><td>1 — sub-pixel rounding</td></tr><tr><td>Bronze</td><td>border</td><td><code>#E2D6CB</code></td><td><code>#E3D6CB</code></td><td>1 — sub-pixel rounding</td></tr><tr><td><strong>Silver</strong></td><td><strong>text</strong></td><td><strong><code>#80858A</code></strong></td><td><strong><code>#8B8D98</code></strong></td><td><strong>14 — real deviation</strong></td></tr></tbody></table><p>Silver&#39;s text is the one place Figma departs from the formula: it uses <code>#8B8D98</code> (= <code>--sp-table-silver</code> / Slate/9) rather than the derived <code>#80858A</code>. The designer chose to keep the pure formula rather than special-case it, so the built component renders <code>#80858A</code>. Both are mid-greys and the difference is barely perceptible, but it is a known divergence — either fix Figma&#39;s Silver text to the derived value, or reinstate an override here.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-spacing-0-5</code></td><td><code>padding</code> block</td><td>2px vertical</td></tr><tr><td><code>--ai-spacing-3</code></td><td><code>padding</code> inline</td><td>8px horizontal</td></tr><tr><td><code>--ai-radius-full</code></td><td><code>border-radius</code></td><td>fully rounded</td></tr><tr><td><code>--ai-font-title</code></td><td><code>font-family</code></td><td>Inter</td></tr><tr><td><code>--ai-font-bold</code></td><td><code>font-weight</code></td><td>700 — <strong>CSS leads Figma</strong>, see below</td></tr><tr><td><code>--ai-font-fixed-5xs</code></td><td><code>font-size</code></td><td>10px</td></tr><tr><td><code>--ai-tracking-7</code></td><td><code>letter-spacing</code></td><td>0.05em — <strong>CSS leads Figma</strong>, see below</td></tr><tr><td>(none)</td><td><code>border-width: 1px</code></td><td>allowed raw-px exception</td></tr></tbody></table><h3 id="typography-the-css-deliberately-leads-figma" tabindex="-1">Typography: the CSS deliberately leads Figma <a class="header-anchor" href="#typography-the-css-deliberately-leads-figma" aria-label="Permalink to &quot;Typography: the CSS deliberately leads Figma&quot;">​</a></h3><p>Amended 2026-08-25 at the designer&#39;s request, ahead of Figma being updated to match:</p><table tabindex="0"><thead><tr><th>Property</th><th>Figma still has</th><th>CSS now uses</th></tr></thead><tbody><tr><td><code>font-weight</code></td><td><code>--ai-font-semibold</code> (600)</td><td><strong><code>--ai-font-bold</code> (700)</strong></td></tr><tr><td><code>letter-spacing</code></td><td><code>--ai-tracking-5</code> (0.0125em)</td><td><strong><code>--ai-tracking-7</code> (0.05em)</strong></td></tr></tbody></table><p><strong>Do not &quot;correct&quot; these back from a Figma fetch.</strong> A future audit that re-reads <code>get_design_context</code> will see 600 / 0.0125em and flag the CSS as wrong — it is not. Figma is the side that is behind until the designer pushes the change. Once Figma is updated, delete this section and the matching comment block in <code>TableType.css</code>.</p><h2 id="token-gaps" tabindex="-1">Token gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token gaps&quot;">​</a></h2><p><strong>All five tier colours are raw hex — user-approved 2026-08-24</strong>, on the grounds that they are picker-set runtime values rather than design values:</p><p><code>#00749e</code> VIP · <code>#991b1b</code> Head Table · <code>#d97706</code> Gold · <code>#abb2b8</code> Silver · <code>#a07553</code> Bronze</p><p>The compositing bases <code>#ffffff</code> and <code>#000000</code> are also raw, deliberately. They are <strong>not</strong><code>--ai-surface-primary</code> / a text token: Figma composites against pure white, and using a theme-aware token would change the formula in dark mode and break the match.</p><h3 id="divergence-from-the-sp-seating-palette-—-worth-reconciling-in-figma" tabindex="-1">Divergence from the <code>--sp-*</code> seating palette — worth reconciling in Figma <a class="header-anchor" href="#divergence-from-the-sp-seating-palette-—-worth-reconciling-in-figma" aria-label="Permalink to &quot;Divergence from the `--sp-*` seating palette — worth reconciling in Figma&quot;">​</a></h3><p>Three of the five tier colours are exactly the Seating Planner tokens; two are not:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Figma base</th><th><code>--sp-*</code> equivalent</th><th>Match?</th></tr></thead><tbody><tr><td>VIP</td><td><code>#00749E</code></td><td><code>--sp-table-vip</code> <code>#00749E</code></td><td>yes</td></tr><tr><td>Head Table</td><td><code>#991B1B</code></td><td><code>--sp-table-head</code> <code>#991B1B</code></td><td>yes</td></tr><tr><td>Bronze</td><td><code>#A07553</code></td><td><code>--sp-table-bronze</code> <code>#A07553</code></td><td>yes</td></tr><tr><td>Gold</td><td><code>#D97706</code> (Amber/600)</td><td><code>--sp-table-gold</code> <code>#CC4E00</code></td><td><strong>no</strong></td></tr><tr><td>Silver</td><td><code>#ABB2B8</code></td><td><code>--sp-table-silver</code> <code>#8B8D98</code></td><td><strong>no</strong> — and <code>#8B8D98</code> appears here as Silver&#39;s <em>text</em></td></tr></tbody></table><p>Left as raw hex for all five so the tiers behave identically. If Gold and Silver are repointed at their <code>--sp-*</code> values in Figma, all five could bind tokens uniformly and the presets would then follow the <code>data-seating</code> mode (Muted / Radix Soft / Radix Vivid).</p><p>Also note <code>--sp-table-press</code> <code>#5C7C2F</code> exists in the palette but has <strong>no Type variant</strong> in this component — six table tiers in the tokens, five in the component.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Dark mode is undefined.</strong> Figma ships only a light treatment, and the formula composites against pure white, so the pill renders identically under <code>[data-theme=&quot;dark&quot;]</code> — a pale tint on a dark surface. Not invented here per the no-fallback rule. Needs a Figma dark variant or an explicit decision. The demo page includes an on-tinted-ground row to make the issue visible.</li><li><strong>Structure simplified to one element.</strong> Figma nests a text node inside a wrapper; the wrapper carries padding/border/radius/background and the child carries typography. Nothing requires two elements, so the component is a single <code>&lt;span class=&quot;table-type&quot;&gt;</code>.</li><li><strong>Semantics:</strong> a non-interactive label, so <code>&lt;span&gt;</code>. No ARIA needed — the text is the content. If it ever becomes a filter control it should become a <code>&lt;button&gt;</code> and gain states.</li><li><strong>No interactive states in Figma</strong> — no hover, focus, selected or disabled variants exist, so none are implemented.</li><li><strong>Figma&#39;s inline px fallbacks are off by one</strong> in the design-context output: <code>px-[var(--ai-spacing-3,9px)]</code> where the token is 8px, and <code>py-[var(--ai-spacing-0-5,3px)]</code> where the token is 2px. The tokens are authoritative and were used; the built height matches Figma&#39;s 18px exactly, which confirms the tokens are right and the fallbacks are the artefact.</li><li><strong>Axis-name discrepancy in tooling:</strong> <code>list_file_components_for_code_connect</code> reports the axis as <code>Property 1</code>, but the variant names are <code>Type=…, Tier=…</code>. The variant names are authoritative — there is no unnamed axis on this component.</li><li><strong>No <code>.figma.ts</code></strong> yet. Code Connect mapping was deliberately declined during the build (there was no code component to map to); it can be added now the component exists.</li></ul>',35)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
